3	namespace App\Http\Middleware\Auth;
4	
5	use App\Models\Core\Staff\SidestStaff;
6	use Closure;
7	use Illuminate\Http\Request;
8	use Symfony\Component\HttpFoundation\Response;
9	
10	// V2: Staff-only gate. Checks supabase_uid maps to a SidestStaff record.
11	class EnsureSidestStaff
12	{
13	    public function handle(Request $request, Closure $next): Response
14	    {
15	        // Set by VerifySupabaseJwt middleware
16	        $uid = $request->attributes->get('supabase_uid');
17	
18	        if (! $uid) {
19	            return response()->json(['message' => 'Unauthenticated'], 401);
20	        }
21	
22	        $staff = SidestStaff::query()
23	            ->where('auth_user_id', $uid)
24	            ->first();
25	
26	        if (! $staff) {
27	            return response()->json(['message' => 'Staff access required'], 403);
28	        }
29	
30	        // Attach for controllers to use
31	        $request->attributes->set('sidest_staff', $staff);
32	
33	        return $next($request);
34	    }
35	}
