11	class EnsureSidestAdmin
12	{
13	    public function handle(Request $request, Closure $next): Response
14	    {
15	        $uid = $request->attributes->get('supabase_uid');
16	
17	        if (! $uid) {
18	            return response()->json(['message' => 'Unauthenticated'], 401);
19	        }
20	
21	        $staff = $request->attributes->get('sidest_staff');
22	
23	        // If EnsureSidestStaff ran before this, we already have the staff record
24	        if (! $staff) {
25	            $staff = SidestStaff::query()->where('auth_user_id', $uid)->first();
26	        }
27	
28	        if (! $staff || $staff->role !== 'admin') {
29	            return response()->json(['message' => 'Admin access required'], 403);
30	        }
31	
32	        $request->attributes->set('sidest_staff', $staff);
33	
34	        return $next($request);
35	    }
36	}
